(function(){
  var qs=['Will your office likely need another assistant sometime in the next year?','Would you rather train someone local than compete for the same experienced hires?','Can your business absorb the cost this quarter without straining cash flow?','Are you genuinely okay if your sponsored student ends up at a different office?','Would you want your business recognized publicly as her sponsor?'];
  var list=document.getElementById('fcList'),out=document.getElementById('fcOut'),ans=[];
  function verdict(){
    var done=0,yes=0;
    for(var i=0;i<qs.length;i++){if(ans[i]!==undefined){done++;if(ans[i]===1)yes++;}}
    if(done<qs.length){out.innerHTML='Answered '+done+' of '+qs.length+'. Finish the list for an honest read.';return;}
    if(yes===5){out.innerHTML='<strong>This is a straightforward fit.</strong> Everything a sponsorship asks of an office lines up for you. Call or text Amanda at (903) 913-6444 and ask who is waiting right now.';}
    else if(yes>=3){out.innerHTML='<strong>Worth a conversation, maybe at a smaller size.</strong> Part of a seat is a real option and often the thing that gets someone started. Start on the <a href="/sponsor-a-student" class="text-teal-700 font-semibold">sponsorship page</a>.';}
    else if(yes>=1){out.innerHTML='<strong>Probably not this year — and that is a fine answer.</strong> Hosting an extern or <a href="/employers/request-graduate" class="text-teal-700 font-semibold">requesting a graduate</a> when you hire costs nothing and still puts you in front of students early.';}
    else{out.innerHTML='<strong>Not your year, and no one will chase you about it.</strong> Keep <a href="/employers/request-graduate" class="text-teal-700 font-semibold">requesting a graduate</a> in your back pocket for when you are hiring.';}
  }
  qs.forEach(function(q,i){
    var row=document.createElement('div');
    row.className='border border-slate-200 rounded-xl p-3';
    row.innerHTML='<div class="text-[15px] text-slate-800 mb-2">'+q+'</div><div class="flex gap-2"><button type="button" class="fcb flex-1 rounded-full py-2 text-sm font-bold border-2 border-slate-300 text-slate-600" data-v="1">Yes</button><button type="button" class="fcb flex-1 rounded-full py-2 text-sm font-bold border-2 border-slate-300 text-slate-600" data-v="0">No</button></div>';
    var btns=row.querySelectorAll('.fcb');
    Array.prototype.forEach.call(btns,function(b){
      b.addEventListener('click',function(){
        ans[i]=+b.getAttribute('data-v');
        Array.prototype.forEach.call(btns,function(o){o.className='fcb flex-1 rounded-full py-2 text-sm font-bold border-2 border-slate-300 text-slate-600';});
        b.className='fcb flex-1 rounded-full py-2 text-sm font-bold border-2 border-teal-600 bg-teal-700 text-white';
        verdict();
      });
    });
    list.appendChild(row);
  });
})();
